# Break My Fix finding 1, generated by Tracefix: Env.db_url returns a wrong value.
# Property (issue): env.db_url(extra_options=...) puts the extra options into the returned config's OPTIONS
# Quote: Perhaps they can be passed in a new `extra_options` argument?
# Run it with pytest: it fails for as long as the code breaks this property.

from environ.environ import Env


def test_break_my_fix_1() -> None:
    self_after = Env()
    var = 'ENVIRON_TEST_UNSET_VAR_XYZ'
    default = 'postgres://user:pass@localhost:5432/db'
    extra_options = {'pool': True}
    # The property applies to this input: var == 'ENVIRON_TEST_UNSET_VAR_XYZ' and isinstance(extra_options, dict) and len(extra_options) > 0 and isinstance(default, str) and default.split('://')[0] in Env.DB_SCHEMES
    result = self_after.db_url(var=var, default=default, extra_options={'pool': True})
    assert ('OPTIONS' in result and all(k in result['OPTIONS'] and result['OPTIONS'][k] == v for k, v in extra_options.items()))
